CREATE TABLE "CatalogueService" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "list" TEXT NOT NULL,
  "code" TEXT NOT NULL,
  "labelAr" TEXT NOT NULL,
  "labelFr" TEXT NOT NULL,
  "labelEn" TEXT NOT NULL,
  "isActive" INTEGER NOT NULL DEFAULT 1,
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL,
  "createdByUserId" TEXT,
  "updatedByUserId" TEXT,
  FOREIGN KEY ("createdByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  FOREIGN KEY ("updatedByUserId") REFERENCES "User" ("id") ON DELETE RESTRICT,
  UNIQUE ("list", "code"),
  CHECK ("list" IN ('PROVIDED','PROGRAMMED')),
  CHECK (length(trim("labelAr")) > 0 AND length(trim("labelFr")) > 0 AND length(trim("labelEn")) > 0)
) STRICT;

CREATE TABLE "CatalogueServiceDivision" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "serviceId" TEXT NOT NULL,
  "division" TEXT NOT NULL,
  "sortOrder" INTEGER NOT NULL,
  "isActive" INTEGER NOT NULL DEFAULT 1,
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL,
  FOREIGN KEY ("serviceId") REFERENCES "CatalogueService" ("id") ON DELETE RESTRICT,
  UNIQUE ("serviceId", "division"),
  CHECK ("division" IN ('HOUSING','ORGANISATION','BUILDING','COMPLEX')),
  CHECK ("sortOrder" >= 0)
) STRICT;
CREATE INDEX "CatalogueServiceDivision_division_sortOrder_idx" ON "CatalogueServiceDivision" ("division", "sortOrder");

CREATE TRIGGER "CatalogueService_no_delete" BEFORE DELETE ON "CatalogueService"
BEGIN SELECT RAISE(ABORT, 'NO_DELETE:CatalogueService'); END;

CREATE TRIGGER "CatalogueServiceDivision_no_delete" BEFORE DELETE ON "CatalogueServiceDivision"
BEGIN SELECT RAISE(ABORT, 'NO_DELETE:CatalogueServiceDivision'); END;

